logs = [(0, 'a'), (5, 'b'), (9, 'c'), (10, 'd'), (12, 'e'), (19, 'f'), (20, 'g'), (25, 'h'), (35, 'i')]
window_size = 10
counts = {}
for ts, msg in logs:
    start = (ts // window_size) * window_size
    end = start + window_size
    key = (start, end)
    counts[key] = counts.get(key, 0) + 1
for (start, end) in sorted(counts):
    print('%d-%d:%d' % (start, end, counts[(start, end)]))

schedule = [('s1', 10), ('s2', 9), ('s1', 8), ('s2', 11), ('s1', 12), ('s2', 7)]
max_ts = {'s1': 0, 's2': 0}
tolerance = 5
def stream_wm(name):
    return max_ts[name] - tolerance
for src, ts in schedule:
    if ts > max_ts[src]:
        max_ts[src] = ts
    global_wm = min(stream_wm('s1'), stream_wm('s2'))
    print('%s:%d -> wm=%d' % (src, ts, global_wm))
